      <div className="editorial-grid">
        {STORIES.map((s, i) => (
          <a key={s.id} href={`#story-${s.id}`} className={"story" + (i === 0 ? " story--feature" : "")} aria-labelledby={`st-${s.id}`}>
            <div className="story__media"><Art {...s.art} /></div>
            <div className="story__body">
              <span className="story__tag">{s.tag}</span>
              <h3 className="story__title" id={`st-${s.id}`}>{s.title}</h3>
              <p className="story__excerpt">{s.excerpt}</p>
              <div className="story__meta"><span>{s.date}</span><span aria-hidden="true">·</span><span>{s.read}</span></div>
            </div>
          </a>
        ))}
      </div>
    </section>
  );
}

function Trust() {
  const items = [
    { icon: Icon.Truck,  title: "Free shipping over $120", sub: "Carbon-neutral delivery" },
    { icon: Icon.Return, title: "60-day returns",          sub: "On unused items" },
    { icon: Icon.Shield, title: "5-year guarantee",        sub: "On all furniture" },
    { icon: Icon.Leaf,   title: "Responsibly sourced",     sub: "FSC-certified materials" },
  ];
  return (
    <section className="container" aria-labelledby="trust-title">
      <h2 id="trust-title" className="sr-only">Why shop with Maison Nord</h2>
      <ul className="trust" role="list">
        {items.map(it => {
          const I = it.icon;
          return (
            <li key={it.title} className="trust__item">
              <span className="trust__icon"><I /></span>
              <span>
                <span className="trust__title" style={{ display: "block" }}>{it.title}</span>
                <span className="trust__sub">{it.sub}</span>
              </span>
            </li>
          );
        })}
      </ul>
    </section>
  );
}

function Newsletter() {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [done, setDone] = useState(false);

  const onSubmit = (e) => {
    e.preventDefault();
    const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    if (!ok) { setError("Please enter a valid email address."); setDone(false); return; }
    setError("");
    setDone(true);
    setEmail("");
  };

  return (
    <section className="container" aria-labelledby="nl-title">
      <div className="newsletter">
        <div>
          <span className="eyebrow">Stay close</span>
          <h2 id="nl-title">Letters from the studio</h2>
          <p>One thoughtful email a fortnight: new arrivals, maker stories, and the occasional reader-only offer.</p>
        </div>
        <form onSubmit={onSubmit} noValidate aria-describedby="nl-help">
          <div className="field">
            <label htmlFor="nl-email">Email address</label>
            <input
              id="nl-email"
              type="email"
              required
              value={email}
              onChange={e => setEmail(e.target.value)}
              placeholder="you@somewhere.co"
              aria-invalid={error ? "true" : "false"}
              aria-describedby={error ? "nl-error nl-help" : "nl-help"}
              autoComplete="email"
            />
            {error && <p id="nl-error" className="error-text" role="alert">{error}</p>}
            <p id="nl-help" className="help-text">No spam, ever. Unsubscribe in one click.</p>
          </div>
          <button type="submit" className="btn btn-primary" style={{ alignSelf: "start", marginTop: 30 }}>Subscribe</button>
          <div className="newsletter__status" aria-live="polite">
            {done && "Thanks — please check your inbox to confirm."}
          </div>
        </form>
      </div>
    </section>
  );
}

function Footer() {
  return (
    <footer className="site-footer" aria-labelledby="footer-title">
      <h2 id="footer-title" className="sr-only">Footer</h2>
      <div className="container">
        <div className="footer-grid">
          <div className="footer-brand">
            <span className="brand">Maison Nord</span>
            <p>Modern essentials for considered living. Designed in Oslo, made across Europe.</p>
            <div className="socials">
              <a href="#instagram" aria-label="Maison Nord on Instagram"><Icon.Instagram /></a>
              <a href="#pinterest" aria-label="Maison Nord on Pinterest"><Icon.Pinterest /></a>
              <a href="#tiktok" aria-label="Maison Nord on TikTok"><Icon.TikTok /></a>
            </div>
          </div>
          <div>
            <h3>Shop</h3>
            <ul>
              <li><a href="#new">New In</a></li>
              <li><a href="#living">Living</a></li>
              <li><a href="#tableware">Tableware</a></li>
              <li><a href="#bedding">Bedding</a></li>
              <li><a href="#sale">Sale</a></li>
            </ul>
          </div>
          <div>
            <h3>Help</h3>
            <ul>
              <li><a href="#shipping">Shipping</a></li>
              <li><a href="#returns">Returns</a></li>
              <li><a href="#care">Care guide</a></li>
              <li><a href="#contact">Contact us</a></li>
            </ul>
          </div>
          <div>
            <h3>Company</h3>
            <ul>
              <li><a href="#about">About</a></li>
              <li><a href="#makers">Our makers</a></li>
              <li><a href="#sustain">Sustainability</a></li>
              <li><a href="#press">Press</a></li>
            </ul>
          </div>
          <div>
            <h3>Legal</h3>
            <ul>
              <li><a href="#privacy">Privacy</a></li>
              <li><a href="#terms">Terms</a></li>
              <li><a href="#cookies">Cookies</a></li>
              <li><a href="#access">Accessibility</a></li>
            </ul>
          </div>
        </div>
        <div className="footer-bottom">
          <span>© 2026 Maison Nord AS · Org. nr. 999 888 777</span>
          <span>Prices in USD · Ships worldwide</span>
        </div>
      </div>
    </footer>
  );
}

/* ---------------- App ---------------- */
function App() {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState(new Set());
  const [toast, setToast] = useState("");

  const onAdd = (p) => {
    setCart(c => [...c, p.id]);
    setToast(`Added ${p.name} to your bag`);
    window.clearTimeout(onAdd._t);
    onAdd._t = window.setTimeout(() => setToast(""), 2500);
  };

  const onWish = (id) => {
    setWishlist(prev => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  return (
    <>
      <Notice />
      <Header cartCount={cart.length} />
      <main id="main">
        <Hero />
        <Categories />
        <Featured onAdd={onAdd} wishlist={wishlist} onWish={onWish} />
        <Deals onAdd={onAdd} />
        <Editorial />
        <Trust />
        <Newsletter />
      </main>
      <Footer />
      <div
        aria-live="polite"
        role="status"
        style={{
          position: "fixed", bottom: 24, left: "50%", transform: "translateX(-50%)",
          background: "#1a1a1a", color: "#fff", padding: toast ? "12px 18px" : 0,
          borderRadius: 999, fontSize: 14, fontWeight: 600,
          opacity: toast ? 1 : 0, transition: "opacity .2s ease",
          pointerEvents: "none", zIndex: 100,
          boxShadow: "0 12px 32px rgba(0,0,0,0.18)"
        }}
      >
        {toast}
      </div>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

