  --bg: #faf8f5;
  --surface: #ffffff;
  --ink: #1a1a1a;
  --ink-2: #4a4a4a;
  --muted: #6b6b6b;
  --line: #e7e3dc;
  --line-strong: #d6d0c4;
  --accent: #8b3a2f;       /* terracotta */
  --accent-ink: #ffffff;
  --sale: #b1442f;
  --tag-bg: #f0ece4;
  --focus: #1f4ed8;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow-sm: 0 1px 2px rgba(20, 14, 6, 0.04), 0 2px 6px rgba(20, 14, 6, 0.04);
  --shadow-md: 0 8px 28px rgba(20, 14, 6, 0.08);
  --container: 1240px;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;
  --space-8: 72px;
  --font-sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-serif: "Fraunces", Georgia, "Times New Roman", serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }

a {
  color: inherit;
  text-decoration: none;
}
a:hover { text-decoration: underline; text-underline-offset: 3px; }

button {
  font: inherit;
  cursor: pointer;
}

/* Focus styles */
:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--ink);
  color: #fff;
  padding: 12px 16px;
  z-index: 1000;
  border-radius: 0 0 8px 0;
}
.skip-link:focus {
  left: 0;
}

.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
}

/* ---------- Top notice bar ---------- */
.notice {
  background: var(--ink);
  color: #f6f1e8;
  text-align: center;
  font-size: 13px;
  letter-spacing: 0.02em;
  padding: 10px 16px;
}
.notice strong { color: #fff; }

/* ---------- Header ---------- */
.site-header {
  background: var(--bg);
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 50;
  backdrop-filter: saturate(140%) blur(6px);
  background-color: rgba(250, 248, 245, 0.92);
}
.site-header__row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  padding: 18px 0;
}
.brand {
  font-family: var(--font-serif);
  font-weight: 600;
  font-size: 26px;
  letter-spacing: -0.01em;
}
.primary-nav {
  display: flex;
  justify-content: center;
}
.primary-nav ul {
  display: flex;
  gap: 28px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.primary-nav a {
  font-size: 14px;
  font-weight: 500;
  color: var(--ink-2);
  padding: 6px 2px;
  border-bottom: 2px solid transparent;
}
.primary-nav a:hover {
  color: var(--ink);
  text-decoration: none;
  border-bottom-color: var(--ink);
}
.utility-nav {
  display: flex;
  align-items: center;
  gap: 6px;
}
.icon-btn {
  background: transparent;
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--ink);
  position: relative;
}
.icon-btn:hover { background: var(--tag-bg); }
.icon-btn svg { width: 20px; height: 20px; }
.cart-count {
  position: absolute;
  top: 2px;
  right: 2px;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  background: var(--accent);
  color: #fff;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.menu-toggle { display: none; }

/* ---------- Hero ---------- */
.hero {
  position: relative;
  margin-top: 24px;
}
.hero__inner {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 0;
  align-items: stretch;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}
.hero__copy {
  padding: 64px 56px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 20px;
}
.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 12px;
  font-weight: 600;
  color: var(--accent);
}
.hero h1 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(36px, 5vw, 60px);
  line-height: 1.05;
  letter-spacing: -0.02em;
  margin: 0;
}
.hero h1 em {
  font-style: italic;
  font-weight: 400;
  color: var(--accent);
}
.hero p.lede {
  font-size: 17px;
  color: var(--ink-2);
  max-width: 46ch;
  margin: 0;
}
.hero__cta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 8px;
}
.hero__media {
  background: #ece6dc;
  position: relative;
  min-height: 420px;
  background-image: linear-gradient(135deg, #d9cfbe 0%, #b8a890 100%);
  overflow: hidden;
}
.hero__media::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 30% 30%, rgba(255,255,255,0.35), transparent 45%),
    radial-gradient(circle at 70% 80%, rgba(0,0,0,0.18), transparent 50%);
}
.hero__media-card {
  position: absolute;
  left: 32px;
  bottom: 32px;
  background: rgba(255,255,255,0.92);
  padding: 14px 18px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  z-index: 1;
}
.hero__media-card .dot {
  width: 8px; height: 8px; border-radius: 999px; background: var(--accent);
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 22px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-weight: 600;
  font-size: 15px;
  letter-spacing: 0.01em;
  transition: transform .08s ease, background .15s ease, color .15s ease, border-color .15s ease;
  text-decoration: none;
  min-height: 44px;
}
.btn:hover { text-decoration: none; transform: translateY(-1px); }
.btn-primary {
  background: var(--ink);
  color: #fff;
}
.btn-primary:hover { background: #000; }
.btn-secondary {
  background: transparent;
  color: var(--ink);
  border-color: var(--line-strong);
}
.btn-secondary:hover { background: var(--surface); border-color: var(--ink); }
.btn-accent {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn-accent:hover { background: #6f2c23; }
.btn-link {
  background: transparent;
  border: none;
  padding: 0;
  color: var(--ink);
  font-weight: 600;
  font-size: 14px;
  text-decoration: underline;
  text-underline-offset: 4px;
  text-decoration-thickness: 1.5px;
}
.btn-link:hover { color: var(--accent); }

/* ---------- Category strip ---------- */
.categories {
  margin-top: 48px;
}
.categories__grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}
.cat-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 20px 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 10px;
  color: var(--ink);
  transition: transform .12s ease, box-shadow .12s ease, border-color .12s ease;
}
.cat-card:hover {
  text-decoration: none;
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  border-color: var(--line-strong);
}
.cat-card__icon {
  width: 56px;
  height: 56px;
  border-radius: 999px;
  background: var(--tag-bg);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
}
.cat-card__icon svg { width: 26px; height: 26px; }
.cat-card__name { font-weight: 600; font-size: 14px; }
.cat-card__count { font-size: 12px; color: var(--muted); }

/* ---------- Section headers ---------- */
.section { margin-top: 72px; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 24px;
}
.section-head h2 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(26px, 3vw, 36px);
  line-height: 1.1;
  letter-spacing: -0.01em;
  margin: 0;
}
.section-head p {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 15px;
}

/* ---------- Product grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product {
  background: transparent;
  display: flex;
  flex-direction: column;
}
.product__media {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  aspect-ratio: 4 / 5;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.product__art {
  width: 100%;
  height: 100%;
  display: block;
}
.product__badges {
  position: absolute;
  top: 12px;
  left: 12px;
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--ink);
  color: #fff;
}
.badge--new { background: #2f5d3a; }
.badge--sale { background: var(--sale); }
.badge--low { background: #8a5a1f; }

.product__wishlist {
  position: absolute;
  top: 10px;
  right: 10px;
  background: rgba(255,255,255,0.92);
  border: none;
  border-radius: 999px;
  width: 38px;
  height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--ink);
}
.product__wishlist:hover { color: var(--accent); }
.product__wishlist[aria-pressed="true"] { color: var(--accent); }
.product__wishlist svg { width: 18px; height: 18px; }

.product__quick {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 12px;
  background: var(--ink);
  color: #fff;
  border: none;
  border-radius: 999px;
  padding: 11px 14px;
  font-weight: 600;
  font-size: 13px;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity .15s ease, transform .15s ease;
}
.product__media:hover .product__quick,
.product__media:focus-within .product__quick {
  opacity: 1;
  transform: translateY(0);
}

.product__info {
  padding: 14px 4px 0;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 12px;
}
.product__cat {
  grid-column: 1 / -1;
  font-size: 12px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 600;
}
.product__name {
  font-size: 15px;
  font-weight: 600;
  color: var(--ink);
  margin: 0;
}
.product__name a:hover { color: var(--accent); text-decoration: none; }
.product__price {
  font-size: 15px;
  font-weight: 600;
  text-align: right;
  white-space: nowrap;
}
.product__price del {
  color: var(--muted);
  font-weight: 400;
  margin-right: 6px;
}
.product__price ins { text-decoration: none; color: var(--sale); }
.product__rating {
  grid-column: 1 / -1;
  margin-top: 4px;
  font-size: 13px;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 6px;
}
.stars {
  color: #c9961f;
  letter-spacing: 1px;
  font-size: 14px;
}

/* ---------- Deals ---------- */
.deals {
  background: linear-gradient(135deg, #1a1a1a 0%, #2a2520 100%);
  color: #f6f1e8;
  border-radius: var(--radius);
  padding: 56px 48px;
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 48px;
  align-items: center;
  margin-top: 72px;
}
.deals__lead .eyebrow { color: #e7b96b; }
.deals__lead h2 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(28px, 3.6vw, 44px);
  line-height: 1.1;
  margin: 12px 0 14px;
  letter-spacing: -0.01em;
}
.deals__lead p {
  color: #d8d2c4;
  font-size: 16px;
  max-width: 42ch;
  margin: 0 0 24px;
}
.countdown {
  display: flex;
  gap: 10px;
  margin-bottom: 24px;
}
.countdown__cell {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.14);
  border-radius: 10px;
  padding: 10px 14px;
  min-width: 64px;
  text-align: center;
}
.countdown__num {
  font-family: var(--font-serif);
  font-size: 26px;
  font-weight: 600;
  color: #fff;
  display: block;
  line-height: 1;
}
.countdown__label {
  display: block;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: #b9b3a4;
  margin-top: 4px;
}
.deals__items {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.deal-card {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 12px;
  padding: 16px;
  display: flex;
  gap: 14px;
  align-items: center;
  color: inherit;
}
.deal-card:hover {
  background: rgba(255,255,255,0.09);
  text-decoration: none;
}
.deal-card__art {
  width: 78px;
  height: 78px;
  border-radius: 8px;
  flex-shrink: 0;
  overflow: hidden;
}
.deal-card__name {
  font-weight: 600;
  font-size: 14px;
  margin: 0 0 4px;
  color: #fff;
}
.deal-card__price {
  font-size: 14px;
  font-weight: 600;
}
.deal-card__price del { color: #a39d8e; font-weight: 400; margin-right: 6px; }
.deal-card__price ins { text-decoration: none; color: #ffb37a; }
.deal-card__off {
  display: inline-block;
  margin-top: 6px;
  background: var(--accent);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  padding: 3px 8px;
  border-radius: 999px;
  text-transform: uppercase;
}

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 24px;
}
.story {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  color: inherit;
}
.story:hover { text-decoration: none; box-shadow: var(--shadow-md); }
.story__media {
  aspect-ratio: 16 / 10;
