  flex-wrap: wrap;
  gap: 12px;
  font-size: 12px;
  color: var(--muted);
}

/* ---------- Visually hidden ---------- */
.sr-only {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
