  letter-spacing: 0.08em;
  font-weight: 600;
}
.product__name {
  font-size: 15px;
  font-weight: 600;
  color: var(--ink);
  margin: 0;
}
.product__name a:hover { color: var(--accent); text-decoration: none; }
.product__price {
  font-size: 15px;
  font-weight: 600;
  text-align: right;
  white-space: nowrap;
}
.product__price del {
  color: var(--muted);
  font-weight: 400;
  margin-right: 6px;
}
.product__price ins { text-decoration: none; color: var(--sale); }
.product__rating {
