    radial-gradient(circle at 70% 80%, rgba(0,0,0,0.18), transparent 50%);
}
.hero__media-card {
  position: absolute;
  left: 32px;
  bottom: 32px;
  background: rgba(255,255,255,0.92);
  padding: 14px 18px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  z-index: 1;
}
.hero__media-card .dot {
  width: 8px; height: 8px; border-radius: 999px; background: var(--accent);
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 22px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-weight: 600;
  font-size: 15px;
