}
.cat-card__icon {
  width: 56px;
  height: 56px;
  border-radius: 999px;
  background: var(--tag-bg);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
}
.cat-card__icon svg { width: 26px; height: 26px; }
.cat-card__name { font-weight: 600; font-size: 14px; }
.cat-card__count { font-size: 12px; color: var(--muted); }

/* ---------- Section headers ---------- */
.section { margin-top: 72px; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 24px;
}
.section-head h2 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(26px, 3vw, 36px);
  line-height: 1.1;
  letter-spacing: -0.01em;
  margin: 0;
}
.section-head p {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 15px;
}

/* ---------- Product grid ---------- */
.product-grid {
  display: grid;
