  display: flex;
  align-items: center;
  justify-content: center;
}
.product__art {
  width: 100%;
  height: 100%;
  display: block;
}
.product__badges {
  position: absolute;
  top: 12px;
  left: 12px;
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--ink);
  color: #fff;
}
.badge--new { background: #2f5d3a; }
.badge--sale { background: var(--sale); }
.badge--low { background: #8a5a1f; }

.product__wishlist {
  position: absolute;
  top: 10px;
  right: 10px;
  background: rgba(255,255,255,0.92);
  border: none;
  border-radius: 999px;
  width: 38px;
  height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--ink);
}
.product__wishlist:hover { color: var(--accent); }
.product__wishlist[aria-pressed="true"] { color: var(--accent); }
.product__wishlist svg { width: 18px; height: 18px; }

.product__quick {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 12px;
  background: var(--ink);
  color: #fff;
  border: none;
  border-radius: 999px;
  padding: 11px 14px;
