}
.product__media:hover .product__quick,
.product__media:focus-within .product__quick {
  opacity: 1;
  transform: translateY(0);
}

.product__info {
  padding: 14px 4px 0;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 12px;
}
.product__cat {
  grid-column: 1 / -1;
  font-size: 12px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 600;
}
.product__name {
  font-size: 15px;
  font-weight: 600;
  color: var(--ink);
  margin: 0;
}
.product__name a:hover { color: var(--accent); text-decoration: none; }
.product__price {
  font-size: 15px;
  font-weight: 600;
  text-align: right;
  white-space: nowrap;
}
.product__price del {
  color: var(--muted);
