  gap: 16px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.deal-card {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 12px;
  padding: 16px;
