}
.deal-card:hover {
  background: rgba(255,255,255,0.09);
  text-decoration: none;
}
.deal-card__art {
  width: 78px;
  height: 78px;
  border-radius: 8px;
  flex-shrink: 0;
  overflow: hidden;
}
.deal-card__name {
  font-weight: 600;
  font-size: 14px;
  margin: 0 0 4px;
  color: #fff;
}
.deal-card__price {
  font-size: 14px;
  font-weight: 600;
}
.deal-card__price del { color: #a39d8e; font-weight: 400; margin-right: 6px; }
.deal-card__price ins { text-decoration: none; color: #ffb37a; }
.deal-card__off {
  display: inline-block;
  margin-top: 6px;
  background: var(--accent);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  padding: 3px 8px;
  border-radius: 999px;
  text-transform: uppercase;
}

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 24px;
}
.story {
  background: var(--surface);
  border: 1px solid var(--line);
